def choose_move(observation):
    def _pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def _sgn(a, b):
        return 0 if a == b else (1 if a > b else -1)

    def _clamp_move(dx, dy):
        if dx < -1:
            dx = -1
        elif dx > 1:
            dx = 1
        if dy < -1:
            dy = -1
        elif dy > 1:
            dy = 1
        return [dx, dy]

    def _manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def _best_target(targets, origin):
        best = None
        best_d = None
        for t in targets:
            if isinstance(t, (list, tuple)) and len(t) >= 2:
                d = _manhattan((t[0], t[1]), origin)
                if best_d is None or d < best_d:
                    best_d = d
                    best = (t[0], t[1])
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = _pos(observation.get("self_position"))
    ox, oy = _pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return _clamp_move(_sgn(ox, sx), _sgn(oy, sy))
        corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        target = None
        best_d = None
        for c in corners:
            d = _manhattan(c, (ox, oy))
            if best_d is None or d > best_d:
                best_d = d
                target = c
        if target is None:
            return [0, 0]
        return _clamp_move(_sgn(target[0], sx), _sgn(target[1], sy))

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        t = _best_target(targets, (sx, sy))
        if t is not None:
            return _clamp_move(_sgn(t[0], sx), _sgn(t[1], sy))
        # If no explicit targets, drift away from opponent to preserve territory.
        return _clamp_move(_sgn(sx, ox), _sgn(sy, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        t = _best_target(resources, (sx, sy))
        if t is not None:
            return _clamp_move(_sgn(t[0], sx), _sgn(t[1], sy))

    # Fallbacks: move toward opponent only in chase-like situations, otherwise stay safe.
    if env == "resource_collection":
        # Slightly prefer separating when adjacent, else head to opponent as a weak proxy for activity.
        if abs(ox - sx) + abs(oy - sy) <= 1:
            return _clamp_move(_sgn(sx, ox), _sgn(sy, oy))
        return _clamp_move(_sgn(ox, sx), _sgn(oy, sy))

